// Comparison only: generated bytes must never depend on the oracle.
import { isDeepStrictEqual } from "node:util";
import { parseIntelHex } from "@jhlagado/debug80-runtime";

function normalize(value) {
  if (typeof value === "string" && value.startsWith(":")) {
    const program = parseIntelHex(value);
    const coverage = new Uint8Array(65536);
    for (const range of program.writeRanges) coverage.fill(1, range.start, range.end);
    return { memory: program.memory, coverage };
  }
  if (Array.isArray(value)) return value.map(normalize);
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, child]) => [key, normalize(child)]));
  }
  return value;
}

function exportsFrom(text) {
  const values = [...text.matchAll(/export const (\w+)(?:: [^=]+)? = ([\s\S]*?);(?:\n|$)/g)]
    .map(([, name, literal]) => [name, JSON.parse(literal.replace(/ as const$/, ""))]);
  if (values.length === 0) throw new Error("No generated image exports found");
  return normalize(Object.fromEntries(values));
}

export function sameGeneratedImages(left, right) {
  // CP/M's generated DB source has canonical formatting and no JSON exports.
  if (!left.includes("export const") && !right.includes("export const")) return left === right;
  return isDeepStrictEqual(exportsFrom(left), exportsFrom(right));
}
